; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: neogeo (SNK Neo Geo (68000)), starts in turbo mode
; ============================================================

			org 0

NTC_RAMEND	equ $10C000		; the end of the RAM the variables and arrays are in (;@ramend)
NTC_A16ADD	equ $110000		; (;@a16) added to a 16 bit address once sign extended: where the RAM's 64K is (0: $FF8000 on, the Mega Drive)
NTC_A16		macro			; an address register loaded from a 16 bit address (movea.w): to the RAM it means
			ifne NTC_A16ADD
			adda.l #NTC_A16ADD, \1
			endif
			endm
;## ntc_md_vectors ntc_ng_boot
; the cartridge's vectors (the BIOS's routines for the exceptions, as every cartridge has them)
; and the Neo Geo header (the compiler puts this first, at 0)
			dc.l $0010F300				; the supervisor stack
			dc.l $00C00402				; reset: the BIOS
			dc.l $00C00408, $00C0040E, $00C00414, $00C0041A	; bus, address, illegal, zero divide
			dc.l $00C0041A, $00C0041A, $00C0041A, $00C00420	; CHK, TRAPV, privilege, trace
			dc.l $00C00426, $00C00426					; line 1010, 1111
			dcb.l 3, $FFFFFFFF			; 12-14
			dc.l $00C0042C				; 15 uninitialised interrupt
			dcb.l 8, $FFFFFFFF			; 16-23
			dc.l $00C00432				; 24 spurious
			dc.l ntc_ng_vbl				; 25 level 1: VBlank
			dc.l ntc_ng_timer			; 26 level 2: the timer
			dc.l ntc_ng_rte				; 27 level 3
			dcb.l 4, ntc_ng_rte			; 28-31
			dcb.l 32, $FFFFFFFF			; 32-63
; the header ($100): test/ngbuild.js puts in the NGH number and the name
			dc.b "NEO-GEO", 0
			dc.w $0C1C					; $108 the NGH number (3100: not $999, which the emulators take for V-Liner)
			dc.l $00100000				; $10A the program's size
			dc.l $0010E800				; $10E an MVS's backup RAM (none used)
			dc.w 0						; $112 its size
			dc.b 1						; $114 the eye-catcher: the game's (USER request 1, which goes straight back)
			dc.b 0						; $115 its first tile
			dc.l ntc_ng_dip, ntc_ng_dip, ntc_ng_dip	; $116 the soft DIPs: Japan, the US, Europe
			dc.w $4EF9					; $122 USER: jmp abs.l (written out: 6 bytes each, at
			dc.l ntc_ng_user			;      the header's fixed places)
			dc.w $4EF9					; $128 PLAYER_START
			dc.l ntc_ng_rts
			dc.w $4EF9					; $12E DEMO_END
			dc.l ntc_ng_rts
			dc.w $4EF9					; $134 COIN_SOUND
			dc.l ntc_ng_rts
			dcb.b 70, $FF				; $13A
			dc.w 0						; $180
			dc.l ntc_ng_scode			; $182 the security code
ntc_ng_scode:
			dc.w $7600, $4A6D, $0A14, $6600, $003C, $206D, $0A04, $3E2D
			dc.w $0A08, $13C0, $0030, $0001, $3210, $0C01, $00FF, $671A
			dc.w $3028, $0002, $B02D, $0ACE, $6610, $3028, $0004, $B02D
			dc.w $0ACF, $6606, $B22D, $0AD0, $6708, $5088, $51CF, $FFD4
			dc.w $3607, $4E75, $206D, $0A04, $3E2D, $0A08, $3210, $E049
			dc.w $0C01, $00FF, $671A, $3010, $B02D, $0ACE, $6612, $3028
			dc.w $0002, $E048, $B02D, $0ACF, $6606, $B22D, $0AD0, $6708
			dc.w $5888, $51CF, $FFD8, $3607, $4E75
ntc_ng_dip:	dc.b "NTC BASIC       "		; the name the BIOS shows (16)
			dc.b $FF, $FF, $FF, $FF		; no time DIPs
			dc.b $FF, $FF				; no number DIPs
			dcb.b 10, 0					; no choice DIPs
			even

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 13: Cls
			dc.l kw_cls

			; 14: Print "VB self test 4"
			dc.l kw_printstrvar, str0
			dc.l kw_printnl

			; 17: Chk LBound(nums), 0
			dc.l p_chk_c, lit_0, lit_0

			; 18: Chk UBound(nums), 5
			dc.l p_chk_c, lit_5, lit_5

			; 19: Chk LBound(odd), 1
			dc.l p_chk_c, lit_1, lit_1

			; 20: Chk UBound(odd), 4
			dc.l p_chk_c, lit_4, lit_4

			; 21: Chk UBound(grid, 2), 3
			dc.l p_chk_c, lit_3, lit_3

			; 24: For i = 0 To 5
			dc.l kw_ztov, var_i
for1_t:

			; 25: nums(i) = 10 - i
			dc.l kw_sublv, 10, var_i, tmp1
			dc.l kw_aset, arr_nums, var_i, tmp1

			; 26: Next
			dc.l kw_next1l, var_i, 5, for1_t
for1_e:

			; 27: Chk Total(nums), 45
			dc.l p_total_c, ad_arr_nums
			dc.l kw_vtov, var_total_total, tmp0
			dc.l p_chk_c, tmp0, lit_45

			; 28: SortUp nums
			dc.l p_sortup_c, ad_arr_nums

			; 29: Chk nums(0), 5
			dc.l p_chk_c, arr_nums, lit_5

			; 30: Chk nums(5), 10
			dc.l p_chk_c, arr_nums+10, lit_10

			; 31: Chk Total(nums), 45
			dc.l p_total_c, ad_arr_nums
			dc.l kw_vtov, var_total_total, tmp0
			dc.l p_chk_c, tmp0, lit_45

			; 32: For i = 1 To 4
			dc.l kw_ltov, 1, var_i
for2_t:

			; 33: odd(i) = i * i
			dc.l kw_mulvv, var_i, var_i, tmp1
			dc.l kw_aset, arr_odd-2, var_i, tmp1

			; 34: Next
			dc.l kw_next1l, var_i, 4, for2_t
for2_e:

			; 35: Chk Total(odd), 30
			dc.l p_total_c, ad_arr_odd
			dc.l kw_vtov, var_total_total, tmp0
			dc.l p_chk_c, tmp0, lit_30

			; 36: Chk Lo(odd), 1
			dc.l p_lo_c, ad_arr_odd
			dc.l kw_vtov, var_lo_lo, tmp0
			dc.l p_chk_c, tmp0, lit_1

			; 37: Chk Hi(odd), 4
			dc.l p_hi_c, ad_arr_odd
			dc.l kw_vtov, var_hi_hi, tmp0
			dc.l p_chk_c, tmp0, lit_4

			; 38: Chk Count(nums), 6
			dc.l p_count_c, ad_arr_nums
			dc.l kw_vtov, var_count_count, tmp0
			dc.l p_chk_c, tmp0, lit_6

			; 39: words(0) = "pear"
			dc.l kw_strcpyn, arr_words, str1, 40

			; 40: words(1) = "apple"
			dc.l kw_strcpyn, arr_words+41, str2, 40

			; 41: words(2) = "fig"
			dc.l kw_strcpyn, arr_words+82, str3, 40

			; 42: ChkS Longest(words), "apple"
			dc.l p_longest_c, ad_arr_words
			dc.l kw_strcpy, stmp0, var_longest_longest
			dc.l p_chks_c, stmp0, str2

			; 43: Shout words
			dc.l p_shout_c, ad_arr_words

			; 44: ChkS words(2), "FIG"
			dc.l p_chks_c, arr_words+82, str4

			; 45: big(0) = 100000
			dc.l kw_l_mov, llit_100000, arr_big

			; 46: big(3) = 250000
			dc.l kw_l_mov, llit_250000, arr_big+12

			; 47: ChkL BigSum(big), 350000
			dc.l p_bigsum_c, ad_arr_big
			dc.l kw_l_mov, var_bigsum_bigsum, ltmp0
			dc.l p_chkl_c, ltmp0, llit_350000

			; 49: Print
			dc.l kw_printnl

			; 50: Print "a"; Tab(6); "b"
			dc.l kw_printstrvar, str5
			dc.l kw_printtab, lit_6
			dc.l kw_printstrvar, str6
			dc.l kw_printnl

			; 51: Print t; " tests, "; bad; " failed"
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str7
			dc.l kw_printint, var_bad
			dc.l kw_printstrvar, str8
			dc.l kw_printnl

			; 52: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str9
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub chk (turbo mode)
; ============================================================

p_chk:

			; 55: t = t + 1
			dc.l kw_inc, var_t

			; 56: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str10

			; 57: If got = want Then
			dc.l kw_cpeqvv, var_chk_got, var_chk_want
			dc.l kw_goto_iffalse, if3_1

			; 58: Print "ok ";
			dc.l kw_printstrvar, str11

			; 59: Else
			dc.l if3_e_go
if3_1:

			; 60: Print "FAIL("; got; ") ";
			dc.l kw_printstrvar, str12
			dc.l kw_printint, var_chk_got
			dc.l kw_printstrvar, str13

			; 61: bad = bad + 1
			dc.l kw_inc, var_bad

			; 62: End If
if3_e:
			dc.l p_chk_r

; ============================================================
; sub chks (turbo mode)
; ============================================================

p_chks:

			; 66: t = t + 1
			dc.l kw_inc, var_t

			; 67: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str10

			; 68: If got = want Then
			dc.l kw_strcmpeq, var_chks_got, var_chks_want
			dc.l kw_goto_iffalse, if4_1

			; 69: Print "ok ";
			dc.l kw_printstrvar, str11

			; 70: Else
			dc.l if4_e_go
if4_1:

			; 71: Print "FAIL["; got; "] ";
			dc.l kw_printstrvar, str14
			dc.l kw_printstrvar, var_chks_got
			dc.l kw_printstrvar, str15

			; 72: bad = bad + 1
			dc.l kw_inc, var_bad

			; 73: End If
if4_e:
			dc.l p_chks_r

; ============================================================
; sub chkl (turbo mode)
; ============================================================

p_chkl:

			; 77: t = t + 1
			dc.l kw_inc, var_t

			; 78: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str10

			; 79: If got = want Then
			dc.l kw_l_cpeq, var_chkl_got, var_chkl_want
			dc.l kw_goto_iffalse, if5_1

			; 80: Print "ok ";
			dc.l kw_printstrvar, str11

			; 81: Else
			dc.l if5_e_go
if5_1:

			; 82: Print "FAIL("; got; ") ";
			dc.l kw_printstrvar, str12
			dc.l kw_l_print, var_chkl_got
			dc.l kw_printstrvar, str13

			; 83: bad = bad + 1
			dc.l kw_inc, var_bad

			; 84: End If
if5_e:
			dc.l p_chkl_r

; ============================================================
; function total (turbo mode)
; ============================================================

p_total:

			; 88: Dim k As Integer

			; 89: Total = 0
			dc.l kw_ztov, var_total_total

			; 90: For k = LBound(a) To UBound(a)
			dc.l kw_lbound, pa_total_a, var_total_k
			dc.l kw_ubound, pa_total_a, for6_l
			dc.l kw_forupv, var_total_k, for6_l, for6_e
for6_t:

			; 91: Total = Total + a(k)
			dc.l kw_pget, pa_total_a, var_total_k, tmp1
			dc.l kw_add, var_total_total, tmp1, var_total_total

			; 92: Next
			dc.l kw_next1v, var_total_k, for6_l, for6_t
for6_e:
			dc.l p_total_r

; ============================================================
; sub sortup (turbo mode)
; ============================================================

p_sortup:

			; 97: Dim k As Integer, j As Integer, v As Integer

			; 98: For k = LBound(a) + 1 To UBound(a)
			dc.l kw_lbound, pa_sortup_a, tmp0
			dc.l kw_addl, tmp0, 1, var_sortup_k
			dc.l kw_ubound, pa_sortup_a, for7_l
			dc.l kw_forupv, var_sortup_k, for7_l, for7_e
for7_t:

			; 99: v = a(k)
			dc.l kw_pget, pa_sortup_a, var_sortup_k, var_sortup_v

			; 100: j = k - 1
			dc.l kw_addl, var_sortup_k, -1, var_sortup_j

			; 101: Do While j >= LBound(a)
do8_t:
			dc.l kw_lbound, pa_sortup_a, tmp1
			dc.l kw_scpgevv, var_sortup_j, tmp1
			dc.l kw_goto_iffalse, do8_e

			; 102: If a(j) <= v Then Exit Do
			dc.l kw_pget, pa_sortup_a, var_sortup_j, tmp0
			dc.l kw_scplevv, tmp0, var_sortup_v
			dc.l kw_goto_iffalse, if9_1
			dc.l do8_e_go
if9_1:

			; 103: a(j + 1) = a(j)
			dc.l kw_addl, var_sortup_j, 1, tmp0
			dc.l kw_pget, pa_sortup_a, var_sortup_j, tmp2
			dc.l kw_pset, pa_sortup_a, tmp0, tmp2

			; 104: j = j - 1
			dc.l kw_dec, var_sortup_j

			; 105: Loop
			dc.l do8_t_go
do8_e:

			; 106: a(j + 1) = v
			dc.l kw_addl, var_sortup_j, 1, tmp0
			dc.l kw_pset, pa_sortup_a, tmp0, var_sortup_v

			; 107: Next
			dc.l kw_next1v, var_sortup_k, for7_l, for7_t
for7_e:
			dc.l p_sortup_r

; ============================================================
; function lo (turbo mode)
; ============================================================

p_lo:

			; 111: Lo = LBound(a)
			dc.l kw_lbound, pa_lo_a, var_lo_lo
			dc.l p_lo_r

; ============================================================
; function hi (turbo mode)
; ============================================================

p_hi:

			; 115: Hi = UBound(a)
			dc.l kw_ubound, pa_hi_a, var_hi_hi
			dc.l p_hi_r

; ============================================================
; function count (turbo mode)
; ============================================================

p_count:

			; 120: Count = Hi(a) - Lo(a) + 1
			dc.l p_hi_c, pa_count_a
			dc.l kw_vtov, var_hi_hi, tmp0
			dc.l p_lo_c, pa_count_a
			dc.l kw_vtov, var_lo_lo, tmp1
			dc.l kw_subvv, tmp0, tmp1, tmp0
			dc.l kw_addl, tmp0, 1, var_count_count
			dc.l p_count_r

; ============================================================
; function longest (turbo mode)
; ============================================================

p_longest:

			; 124: Dim k As Integer

			; 125: Longest = ""
			dc.l kw_strcpy, var_longest_longest, str16

			; 126: For k = 0 To UBound(s)
			dc.l kw_ztov, var_longest_k
			dc.l kw_ubound, pa_longest_s, for10_l
			dc.l kw_forupv, var_longest_k, for10_l, for10_e
for10_t:

			; 127: If Len(s(k)) > Len(Longest) Then Longest = s(k)
			dc.l kw_pget, pa_longest_s, var_longest_k, stmp0
			dc.l kw_strlen, stmp0, tmp0
			dc.l kw_strlen, var_longest_longest, tmp1
			dc.l kw_scpgtvv, tmp0, tmp1
			dc.l kw_goto_iffalse, if11_1
			dc.l kw_pget, pa_longest_s, var_longest_k, var_longest_longest
if11_1:

			; 128: Next
			dc.l kw_next1v, var_longest_k, for10_l, for10_t
for10_e:
			dc.l p_longest_r

; ============================================================
; sub shout (turbo mode)
; ============================================================

p_shout:

			; 132: Dim k As Integer

			; 133: For k = 0 To UBound(s)
			dc.l kw_ztov, var_shout_k
			dc.l kw_ubound, pa_shout_s, for12_l
			dc.l kw_forupv, var_shout_k, for12_l, for12_e
for12_t:

			; 134: s(k) = UCase$(s(k))
			dc.l kw_pget, pa_shout_s, var_shout_k, stmp2
			dc.l kw_strucase, stmp2, stmp2
			dc.l kw_psets, pa_shout_s, var_shout_k, stmp2

			; 135: Next
			dc.l kw_next1v, var_shout_k, for12_l, for12_t
for12_e:
			dc.l p_shout_r

; ============================================================
; function bigsum (turbo mode)
; ============================================================

p_bigsum:

			; 139: Dim k As Integer

			; 140: BigSum = 0
			dc.l kw_l_mov, llit_0, var_bigsum_bigsum

			; 141: For k = 0 To UBound(v)
			dc.l kw_ztov, var_bigsum_k
			dc.l kw_ubound, pa_bigsum_v, for13_l
			dc.l kw_forupv, var_bigsum_k, for13_l, for13_e
for13_t:

			; 142: BigSum = BigSum + v(k)
			dc.l kw_pget, pa_bigsum_v, var_bigsum_k, ltmp1
			dc.l kw_l_add, var_bigsum_bigsum, ltmp1, var_bigsum_bigsum

			; 143: Next
			dc.l kw_next1v, var_bigsum_k, for13_l, for13_t
for13_e:
			dc.l p_bigsum_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if3_e_go:			lea if3_e, sp
			rts
if4_e_go:			lea if4_e, sp
			rts
if5_e_go:			lea if5_e, sp
			rts
do8_e_go:			lea do8_e, sp
			rts
do8_t_go:			lea do8_t, sp
			rts

p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_chks_c:		; call chks
			movea.l (sp)+, a0		; got
			lea var_chks_got, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si0_e
p_chks_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si0
			beq p_chks_si0_z
p_chks_si0_e:
			clr.b (a1)
p_chks_si0_z:
			movea.l (sp)+, a0		; want
			lea var_chks_want, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si1_e
p_chks_si1:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si1
			beq p_chks_si1_z
p_chks_si1_e:
			clr.b (a1)
p_chks_si1_z:
			move.l sp, p_chks_rs
			lea p_chks, sp
			rts
p_chks_r:		; end of chks
			movea.l p_chks_rs, sp
			rts
p_chkl_c:		; call chkl
			movea.l (sp)+, a0		; got
			move.l (a0), var_chkl_got
			movea.l (sp)+, a0		; want
			move.l (a0), var_chkl_want
			move.l sp, p_chkl_rs
			lea p_chkl, sp
			rts
p_chkl_r:		; end of chkl
			movea.l p_chkl_rs, sp
			rts
p_total_c:		; call total
			movea.l (sp)+, a0		; a() descriptor
			lea pa_total_a, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_total_total
			clr.w var_total_k
			move.l sp, p_total_rs
