			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_sortup_k
			clr.w var_sortup_j
			clr.w var_sortup_v
			move.l sp, p_sortup_rs
