			rts
p_hi_c:		; call hi
			movea.l (sp)+, a0		; a() descriptor
			lea pa_hi_a, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_hi_hi
