			rts
p_count_c:		; call count
			movea.l (sp)+, a0		; a() descriptor
			lea pa_count_a, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_count_count
			move.l sp, p_count_rs
			lea p_count, sp
			rts
p_count_r:		; end of count
			movea.l p_count_rs, sp
			rts
p_longest_c:		; call longest
			movea.l (sp)+, a0		; s() descriptor
			lea pa_longest_s, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.b var_longest_longest
			clr.w var_longest_k
			move.l sp, p_longest_rs
			lea p_longest, sp
			rts
p_longest_r:		; end of longest
