; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d1
			cmp.w (a0), d1
			blt ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			addq.w #1, (a0)
			bvs ntc_for_skip
			move.w (a1), d1
			cmp.w (a0), d1
			bge ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_dec
kw_dec:
			movea.l (sp)+, a0
			subq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			move.l (sp)+, d0
			movea.l (sp)+, a1
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvv
;kw_mulvv, <var1>, <var2>, <destvar>  - low 16 bits
kw_mulvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			muls.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scplevv ntc_cmp
kw_scplevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sle

			even
;## kw_scpgtvv ntc_cmp
kw_scpgtvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sgt

			even
;## kw_scpgevv ntc_cmp
kw_scpgevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sge

			even
;## kw_cpeqvv
kw_cpeqvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			cmp.w (a1), d0
			rts

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcpyn kw_strcpy
;kw_strcpyn, <destaddr>, <srcaddr>, <capacity>  - into an array element (no capacity byte)
kw_strcpyn:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (sp)+, d1
			andi.w #$FF, d1
			bra ntc_strcpy_lp

			even
;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			movea.l (sp)+, a0
			moveq #-1, d0
kw_sl_lp:
			addq.w #1, d0
			tst.b (a0)+
			bne kw_sl_lp
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printtab ntc_data ntc_plat_screen
;kw_printtab, <nvar>  - Tab(n) in Print: spaces up to column n (1 based),
;  a new line first when the cursor is already past it. n off the line: nothing
kw_printtab:
			movea.l (sp)+, a0
			move.w (a0), d2
			subq.w #1, d2
ntc_pt_go:						; d2 = the column (0 based)
			moveq #0, d0
			move.b ntc_scols, d0
			cmp.w d0, d2
			bcc ntc_pt_end			; (also below 0: unsigned)
			NTC_RS
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bcc ntc_pt_lp
			jsr ntc_plat_newline
ntc_pt_lp:
			moveq #0, d0
			move.b ntc_curx, d0
			cmp.w d0, d2
			bls ntc_pt_done
			moveq #' ', d0
			jsr ntc_plat_putc
			bra ntc_pt_lp
ntc_pt_done:
			NTC_TS
ntc_pt_end:
			rts

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_cls ntc_data ntc_plat_screen
kw_cls:
			NTC_RS
			jsr ntc_plat_cls
			NTC_TS
			rts

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## ntc_paddr
; a0 = descriptor, a1 = index var: a0 = element address, d1 = element size. jmp (a6)
ntc_paddr:
			move.w (a1), d0
			sub.w 2(a0), d0				; element number
ntc_pa_tail:					; d0.w = element number, a0 = descriptor
			move.w 10(a0), d1
			movea.w (a0), a0
			NTC_A16 a0
			muls.w d1, d0
			adda.l d0, a0
			jmp (a6)

			even
;## kw_pget ntc_paddr
;kw_pget, <descriptor>, <indexvar>, <dest>  - dest = parameter array(index)
kw_pget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pg_a, a6
			bra ntc_paddr
kw_pg_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: into the Integer's low byte
			bne kw_pg_n1
			clr.b (a1)+
kw_pg_n1:
			subq.w #1, d1
kw_pg_lp:
			move.b (a0)+, (a1)+
			dbra d1, kw_pg_lp
			rts

			even
;## kw_pset ntc_paddr
;kw_pset, <descriptor>, <indexvar>, <src>  - parameter array(index) = src
kw_pset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_ps_a, a6
			bra ntc_paddr
kw_ps_a:
			movea.l (sp)+, a1
			cmpi.w #1, d1				; a Byte element: from the Integer's low byte
			bne kw_ps_n1
			addq.l #1, a1
kw_ps_n1:
			subq.w #1, d1
kw_ps_lp:
			move.b (a1)+, (a0)+
			dbra d1, kw_ps_lp
			rts

			even
;## kw_psets ntc_paddr kw_strcpy
;kw_psets, <descriptor>, <indexvar>, <src>  - String parameter array(index) = src
kw_psets:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			lea kw_pss_a, a6
			bra ntc_paddr
kw_pss_a:
			movea.l a0, a1
			movea.l (sp)+, a0
			subq.w #1, d1
			bra ntc_strcpy_lp

			even
;## kw_lbound
;kw_lbound, <descriptor + 2 * (dimension - 1)>, <dest>  - LBound
kw_lbound:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## kw_ubound
;kw_ubound, <descriptor + 2 * (dimension - 1)>, <dest>  - UBound = lower bound + count - 1
kw_ubound:
			movea.l (sp)+, a0
			move.w 2(a0), d0
			add.w 6(a0), d0
			subq.w #1, d0
			movea.l (sp)+, a1
			move.w d0, (a1)
			rts

; ============================================================
; Long (32 bit signed): a 68000 long. Every argument is an address
; (a literal is a dc.l in the ROM).
; ============================================================

			even
;## kw_l_mov
kw_l_mov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), (a1)
			rts

			even
;## kw_l_add
kw_l_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			add.l (a1), d0
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_cpeq
kw_l_cpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			cmp.l (a1), d0
			rts

			even
;## ntc_ltoa ntc_data
; the Long d0 to text at a1, a 0 at the end (a1 on it). jmp (a6). Uses d0-d3, a0
ntc_ltoa:
			tst.l d0
			bpl ntc_lta_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_lta_pos:
			lea ntc_lta_tmp+12, a0
			clr.b -(a0)
ntc_lta_lp:
			; d0 unsigned / 10: high word first
			move.l d0, d2
			clr.w d2
			swap d2
			divu.w #10, d2				; d2 = rem:quot of the high word
			move.w d2, d3				; the quotient's high word
			move.w d0, d2				; rem (high) : low word
			divu.w #10, d2
			swap d3
			move.w d2, d3				; d3 = the quotient
			swap d2
			addi.b #'0', d2
			move.b d2, -(a0)
			move.l d3, d0
			bne ntc_lta_lp
ntc_lta_cp:
			move.b (a0)+, (a1)+
			bne ntc_lta_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_l_print ntc_ltoa ntc_printbuf
kw_l_print:
			movea.l (sp)+, a0
			move.l (a0), d0
			lea ntc_numbuf, a1
			lea kw_lpr_b, a6
			bra ntc_ltoa
kw_lpr_b:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #NTC_RAMEND, d1		; (the platform's ;@ramend, written by the compiler: $01000000 on the Mega Drive)
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen ntc_ng_snd
; ------------------------------------------------------------
; USER (the BIOS calls it, supervisor mode): request 0 / 1 back to the BIOS;
; 2 / 3: RAM cleared and the RAM block copied from the ROM, the screen, the
; sound driver's count; then user mode on the real stack and into ntc_start
; ------------------------------------------------------------
REG_P1CNT		equ $300000
REG_WATCHDOG	equ $300001
REG_SOUND		equ $320000
REG_P2CNT		equ $340000
REG_STATUSB		equ $380000
REG_SWPROM		equ $3A0013
REG_CRTFIX		equ $3A001B
REG_PALBANK0	equ $3A001F
REG_VRAMADDR	equ $3C0000
REG_VRAMRW		equ $3C0002
REG_VRAMMOD		equ $3C0004
REG_LSPCMODE	equ $3C0006
REG_IRQACK		equ $3C000C
NG_PALRAM		equ $400000
BIOS_SYSTEM_MODE	equ $10FD80
BIOS_USER_REQUEST	equ $10FDAE
NG_FIXMAP		equ $7000
NTC_USTACK		equ $0010E800			; the real stack's top
ntc_ng_user:
			move.b d0, REG_WATCHDOG
			move.b BIOS_USER_REQUEST, d0
			cmpi.b #2, d0
			bcc ntc_ng_game
			jmp $00C00444				; SYSTEM_RETURN
ntc_ng_rts:
			rts
ntc_ng_game:
			move.w #$2700, sr
			move.w #7, REG_IRQACK
			move.b d0, REG_WATCHDOG
			lea $00100000, a0			; RAM cleared, up to the real stack's top
			move.w #($E800/4)-1, d0
ntc_nb_clr:
			clr.l (a0)+
			dbra d0, ntc_nb_clr
			move.b d0, REG_WATCHDOG
			lea ntc_romend, a0			; the RAM block's first image, from the ROM
			lea ntc_ram, a1
			move.l #ntc_ramend-ntc_ram, d0
			beq ntc_nb_nodata
ntc_nb_cp:
			move.b (a0)+, (a1)+
			subq.l #1, d0
			bne ntc_nb_cp
ntc_nb_nodata:
			move.b d0, REG_WATCHDOG
			move.b #1, REG_CRTFIX		; the cartridge's fix tiles
			move.b d0, REG_PALBANK0
			move.w #0, REG_LSPCMODE		; no auto-animation timer
			move.w #1, REG_VRAMMOD
			move.w #$8000, REG_VRAMADDR	; every sprite full size
			move.w #$200-1, d0
ntc_nb_scb2:
			move.w #$0FFF, REG_VRAMRW
			dbra d0, ntc_nb_scb2
			move.w #$8200, REG_VRAMADDR	; and hidden (0 tall)
			move.w #$200-1, d0
ntc_nb_scb3:
			move.w #0, REG_VRAMRW
			dbra d0, ntc_nb_scb3
			move.w #$8400, REG_VRAMADDR	; x 0
			move.w #$200-1, d0
ntc_nb_scb4:
			move.w #0, REG_VRAMRW
			dbra d0, ntc_nb_scb4
			move.b d0, REG_WATCHDOG
			lea NG_PALRAM, a0			; the palettes: black; palette 0 colour 1 white
			move.w #$2000/4-1, d0
ntc_nb_pal:
			move.l #$80008000, (a0)+
			dbra d0, ntc_nb_pal
			move.w #$7FFF, NG_PALRAM+2
			move.b d0, REG_WATCHDOG
			move.b #40, ntc_scols
			move.b #28, ntc_srows
			move.b #$00, ntc_tattr
			jsr ntc_plat_cls
			move.b REG_SOUND, ntc_ngseq	; the sound driver's count so far
			move.l #NTC_USTACK, a0
			move.l a0, usp
			move.w #$0000, sr			; user mode, the interrupts on: A7 is now the user stack
			jmp ntc_start

; ------------------------------------------------------------
; interrupts (supervisor mode)
; ------------------------------------------------------------
; VBlank: until the game runs it is the BIOS's; then acknowledged, the
; watchdog kicked, counted, the pads read, the frame hook run
ntc_ng_vbl:
			btst #7, BIOS_SYSTEM_MODE
			bne ntc_nv_game
			jmp $00C00438				; SYSTEM_INT1
ntc_nv_game:
			move.w #4, REG_IRQACK
			move.b d0, REG_WATCHDOG
			movem.l d0-d4/a0-a1, -(sp)
			addq.w #1, ntc_ticks
			addq.w #1, ntc_vbl
			move.b REG_STATUSB, d2
			not.b d2
			move.b REG_P1CNT, d0
			not.b d0
			andi.w #$FF, d0
			btst #0, d2
			beq ntc_nv_s1
			bset #8, d0					; Start
ntc_nv_s1:
			btst #1, d2
			beq ntc_nv_e1
			bset #9, d0					; Select
ntc_nv_e1:
			move.w d0, ntc_pad1
			move.b REG_P2CNT, d0
			not.b d0
			andi.w #$FF, d0
			btst #2, d2
			beq ntc_nv_s2
			bset #8, d0
ntc_nv_s2:
			btst #3, d2
			beq ntc_nv_e2
			bset #9, d0
ntc_nv_e2:
			move.w d0, ntc_pad2
			move.l ntc_vhook, d0
			beq ntc_nv_nohook
			movea.l d0, a0
			jsr (a0)					; (keeps every register but d0-d4 / a0-a1)
ntc_nv_nohook:
			movem.l (sp)+, d0-d4/a0-a1
ntc_ng_rte:
			rte
ntc_ng_timer:
			move.w #2, REG_IRQACK
			rte

			even
;## ntc_ng_snd ntc_plat_data
; ntc_ng_snd - d0.b = a byte for the Z80's sound driver: sent, and its answer waited for (the
; driver answers each byte with its count of them; a dead or busy Z80 is given up on after a
; while). Real stack, keeps every register
ntc_ng_snd:
			movem.l d0-d1, -(sp)
			move.b d0, REG_SOUND
			move.b ntc_ngseq, d0
			addq.b #1, d0
			move.w #4000, d1
ntc_ns_wait:
			cmp.b REG_SOUND, d0
			beq ntc_ns_ok
			dbra d1, ntc_ns_wait
			move.b REG_SOUND, d0		; no answer: take what it says now
ntc_ns_ok:
			move.b d0, ntc_ngseq
			movem.l (sp)+, d0-d1
			rts

			even
;## ntc_plat_data

			even
;## ntc_plat_screen ntc_plat_data ntc_data ntc_ng_logs
; ntc_plat_putc - d0.b = character: in the fix layer at the cursor, move on, a
; new line after the last column. Real stack, keeps d2-d7 / a2-a6
ntc_plat_putc:
			movem.l d0-d2/a0, -(sp)
		ifd NTC_NGLOG
			bsr ntc_ng_log
		endif
			moveq #0, d1
			move.b ntc_cury, d1
			mulu.w #40, d1
			moveq #0, d2
			move.b ntc_curx, d2
			add.w d2, d1
			lea ntc_shadow, a0
			move.b d0, 0(a0, d1.w)
			bsr ntc_ng_cell			; d0 = char, the cursor's cell
			addq.b #1, ntc_curx
			move.b ntc_curx, d0
			cmp.b ntc_scols, d0
			bcs ntc_pc_nowrap
			move.b #1, ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			bra ntc_nl_do
ntc_pc_nowrap:
			clr.b ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			rts

; the cell at the cursor gets character d0 (the fix map: 32 cells a column, the text from row 2)
ntc_ng_cell:
			movem.l d0-d1, -(sp)
			moveq #0, d1
			move.b ntc_curx, d1
			lsl.w #5, d1
			moveq #2, d0
			add.b ntc_cury, d0
			add.w d0, d1
			addi.w #NG_FIXMAP, d1
			move.w d1, REG_VRAMADDR
			movem.l (sp)+, d0-d1
			move.l d1, -(sp)
			moveq #0, d1
			move.b ntc_tattr, d1
			lsl.w #8, d1
			move.b d0, d1
			add.w ntc_tbase, d1
			move.w d1, REG_VRAMRW
			move.l (sp)+, d1
			rts

; ntc_plat_newline - column 0, next row (scrolls at the bottom); nothing straight after a wrap
ntc_plat_newline:
		ifd NTC_NGLOG
			move.l d0, -(sp)
			moveq #10, d0
			bsr ntc_ng_log
			move.l (sp)+, d0
		endif
			tst.b ntc_wrapped
			beq ntc_nl_do
			clr.b ntc_wrapped
			rts
ntc_nl_do:
			clr.b ntc_curx
			addq.b #1, ntc_cury
			move.b ntc_cury, d0
			cmp.b ntc_srows, d0
			bcs ntc_nl_e
			subq.b #1, ntc_cury
			bra ntc_ng_scroll
ntc_nl_e:
			rts

; the text up a row: the shadow moved up, the last row cleared, the fix layer redrawn
ntc_ng_scroll:
			movem.l d0-d3/a0-a1, -(sp)
			lea ntc_shadow, a0
			lea 40(a0), a1
			move.w #40*27-1, d0
ntc_sc_mv:
			move.b (a1)+, (a0)+
			dbra d0, ntc_sc_mv
			moveq #40-1, d0
ntc_sc_cl:
			move.b #' ', (a0)+
			dbra d0, ntc_sc_cl
			bsr ntc_ng_redraw
			movem.l (sp)+, d0-d3/a0-a1
			rts

; the fix layer from the shadow (28 rows of 40): a column at a time (the fix map runs down)
ntc_ng_redraw:
			movem.l d0-d3/a0, -(sp)
			move.w #32, REG_VRAMMOD
			moveq #0, d2				; row
			moveq #0, d3
			move.b ntc_tattr, d3
			lsl.w #8, d3
ntc_rd_row:
			move.w d2, d0
			addi.w #NG_FIXMAP+2, d0
			move.w d0, REG_VRAMADDR
			lea ntc_shadow, a0
			move.w d2, d0
			mulu.w #40, d0
			adda.w d0, a0
			moveq #40-1, d1
ntc_rd_col:
			moveq #0, d0
			move.b (a0)+, d0
			bne ntc_rd_ch
			moveq #' ', d0
ntc_rd_ch:
			or.w d3, d0
			add.w ntc_tbase, d0
			move.w d0, REG_VRAMRW
			dbra d1, ntc_rd_col
			addq.w #1, d2
			cmpi.w #28, d2
			bcs ntc_rd_row
			move.w #1, REG_VRAMMOD
			movem.l (sp)+, d0-d3/a0
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_cls - clear the console, the cursor home
ntc_plat_cls:
			movem.l d0/a0, -(sp)
			lea ntc_shadow, a0
			move.w #40*28-1, d0
ntc_cls_lp:
			move.b #' ', (a0)+
			dbra d0, ntc_cls_lp
			clr.b ntc_curx
			clr.b ntc_cury
			clr.b ntc_wrapped
			bsr ntc_ng_redraw
			movem.l (sp)+, d0/a0
			rts

			even
;## ntc_ng_logs
		ifd NTC_NGLOG
; test builds (vasm -DNTC_NGLOG): what the console was given, at $10C000 on (the
; harness reads it): characters, 10 for a new line. $10DFFC: where the next goes
ntc_ng_log:
			move.l a0, -(sp)
			movea.l $0010DFFC, a0
			cmpa.l #$0010C000, a0
			bcc ntc_lg_ok
			lea $0010C000, a0
ntc_lg_ok:
			cmpa.l #$0010DFF0, a0
			bcc ntc_lg_full
			move.b d0, (a0)+
			move.l a0, $0010DFFC
ntc_lg_full:
			movea.l (sp)+, a0
			rts
		endif

			even
;## ntc_plat_key ntc_data ntc_plat_data ntc_plat_frame
; ntc_plat_scankey - d0 = the code of a button newly pressed on pad 1, or 0
ntc_plat_scankey:
			movem.l d1-d2/a0, -(sp)
			move.w ntc_pad1, d1
			move.w ntc_padseen, d2
			move.w d1, ntc_padseen
			not.w d2
			and.w d2, d1				; the new ones
			moveq #0, d0
			lea ntc_ng_keys, a0
			moveq #0, d2
ntc_sk_lp:
			btst d2, d1
			bne ntc_sk_got
			addq.w #1, d2
			cmpi.w #10, d2
			bcs ntc_sk_lp
			bra ntc_sk_e
ntc_sk_got:
			move.b 0(a0, d2.w), d0
ntc_sk_e:
			movem.l (sp)+, d1-d2/a0
			rts
ntc_ng_keys:	dc.b $F0, $F1, $F2, $F3, 'A', 'B', 'C', 'D', 13, 27
			even

; ntc_plat_getkey - wait for a button: d0 = its code
ntc_plat_getkey:
			bsr ntc_plat_scankey
			tst.b d0
			bne ntc_gk_e
			bsr ntc_plat_frame
			bra ntc_plat_getkey
ntc_gk_e:
			rts

			even
;## ntc_plat_frame ntc_plat_data
; ntc_plat_frame - wait for the next VBlank interrupt
ntc_plat_frame:
			move.l d0, -(sp)
			move.w ntc_vbl, d0
ntc_fr_lp:
			cmp.w ntc_vbl, d0
			beq ntc_fr_lp
			move.l (sp)+, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - before the program stops: nothing to give back (the watchdog is kicked by the
; VBlank interrupt, so a stopped program sits still rather than resetting)
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $100000		; (;@ramorg: where this platform's variables are - 16 bit addresses, sign extended)
ntc_ram:
; variables
var_i:			dc.w 0
ad_arr_nums:			dc.w (arr_nums)&$FFFF, (0)&$FFFF, (0)&$FFFF, (6)&$FFFF, (1)&$FFFF, (2)&$FFFF		; array as an argument
var_total_total:			dc.w 0
ad_arr_odd:			dc.w (arr_odd)&$FFFF, (1)&$FFFF, (0)&$FFFF, (4)&$FFFF, (1)&$FFFF, (2)&$FFFF		; array as an argument
var_lo_lo:			dc.w 0
var_hi_hi:			dc.w 0
var_count_count:			dc.w 0
ad_arr_words:			dc.w (arr_words)&$FFFF, (0)&$FFFF, (0)&$FFFF, (3)&$FFFF, (1)&$FFFF, (41)&$FFFF		; array as an argument
			dc.b 40			; capacity
var_longest_longest:			ds.b 41
			even
ad_arr_big:			dc.w (arr_big)&$FFFF, (0)&$FFFF, (0)&$FFFF, (4)&$FFFF, (1)&$FFFF, (4)&$FFFF		; array as an argument
var_bigsum_bigsum:			dc.l 0
var_t:			dc.w 0
var_bad:			dc.w 0
p_chk_rs:			dc.l 0
var_chk_got:			dc.w 0
var_chk_want:			dc.w 0
p_chks_rs:			dc.l 0
			dc.b 40			; capacity
var_chks_got:			ds.b 41
			even
			dc.b 40			; capacity
var_chks_want:			ds.b 41
			even
p_chkl_rs:			dc.l 0
var_chkl_got:			dc.l 0
var_chkl_want:			dc.l 0
p_total_rs:			dc.l 0
var_total_k:			dc.w 0
for6_l:			dc.w 0
p_sortup_rs:			dc.l 0
var_sortup_k:			dc.w 0
var_sortup_j:			dc.w 0
var_sortup_v:			dc.w 0
for7_l:			dc.w 0
p_lo_rs:			dc.l 0
p_hi_rs:			dc.l 0
p_count_rs:			dc.l 0
p_longest_rs:			dc.l 0
var_longest_k:			dc.w 0
for10_l:			dc.w 0
p_shout_rs:			dc.l 0
var_shout_k:			dc.w 0
for12_l:			dc.w 0
p_bigsum_rs:			dc.l 0
var_bigsum_k:			dc.w 0
for13_l:			dc.w 0
tmp0:			dc.w 0
tmp1:			dc.w 0
tmp2:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			dc.b 40			; capacity
stmp1:			ds.b 41
			even
			dc.b 40			; capacity
stmp2:			ds.b 41
			even
ltmp0:			dc.l 0
ltmp1:			dc.l 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_lta_tmp:	ds.b 12
			even
ntc_curx:		dc.b 0				; cursor column (0 based)
ntc_cury:		dc.b 0				; cursor row (0 based)
ntc_scols:		dc.b 40				; columns
ntc_srows:		dc.b 28				; rows
ntc_wrapped:	dc.b 0				; 1 = the last character wrapped to the next line
ntc_tattr:		dc.b $00			; the text cells' palette (high 4 bits)
ntc_ngseq:		dc.b 0				; the sound driver's count of the bytes it has taken
				dc.b 0
ntc_tbase:		dc.w 0				; added to a character for its fix tile (another font)
ntc_ticks:		dc.w 0				; frames since the start
ntc_vbl:		dc.w 0				; frames (ntc_plat_frame waits for it to move)
ntc_pad1:		dc.w 0				; pad 1's buttons now (bit 0 Up ... 7 D, 8 Start, 9 Select)
ntc_pad2:		dc.w 0
ntc_padseen:	dc.w 0				; pad 1 as Inkey last saw it (new presses only)
ntc_vhook:		dc.l 0				; a routine the VBlank interrupt runs (supervisor mode), 0 none
ntc_shadow:		ds.b 40*28			; the console's text
			even
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_nums		equ ntc_bss + 0		; 12 bytes
arr_odd		equ ntc_bss + 12		; 8 bytes
arr_words		equ ntc_bss + 20		; 123 bytes
arr_big		equ ntc_bss + 144		; 16 bytes
arr_grid		equ ntc_bss + 160		; 24 bytes
pa_total_a		equ ntc_bss + 184		; 12 bytes
pa_sortup_a		equ ntc_bss + 196		; 12 bytes
pa_lo_a		equ ntc_bss + 208		; 12 bytes
pa_hi_a		equ ntc_bss + 220		; 12 bytes
pa_count_a		equ ntc_bss + 232		; 12 bytes
pa_longest_s		equ ntc_bss + 244		; 12 bytes
pa_shout_s		equ ntc_bss + 256		; 12 bytes
pa_bigsum_v		equ ntc_bss + 268		; 12 bytes
ntc_bss_size	equ 280
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
